<?php $pageTitle='Auctions';require __DIR__.'/_top.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare("INSERT INTO auctions(title,flower_id,starts_at,ends_at,base_price,status) VALUES(?,?,?,?,?,'scheduled')")->execute([trim($_POST['title']),(int)$_POST['flower_id']?:null,$_POST['starts_at'],$_POST['ends_at']?:null,(float)$_POST['base_price']]);flash('Auction scheduled.');header('Location: '.url('admin/auctions.php'));exit;}$flowers=$pdo->query("SELECT id,name FROM flowers WHERE status='active'")->fetchAll();$rows=$pdo->query("SELECT a.*,f.name flower_name FROM auctions a LEFT JOIN flowers f ON f.id=a.flower_id ORDER BY a.starts_at DESC")->fetchAll();$f=get_flash(); ?>
<?php if($f): ?><p class="notice"><?= e($f[0]) ?></p><?php endif; ?><div class="admin-columns"><section class="panel"><h2>Schedule an auction</h2><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><label>Auction title<input required name="title"></label><label>Flower<select name="flower_id"><option value="0">Select flower</option><?php foreach($flowers as $fl): ?><option value="<?= (int)$fl['id'] ?>"><?= e($fl['name']) ?></option><?php endforeach; ?></select></label><label>Start date and time<input required type="datetime-local" name="starts_at"></label><label>End date and time<input type="datetime-local" name="ends_at"></label><label>Base price (₹)<input required type="number" min="0" step=".01" name="base_price"></label><button class="btn btn-primary">Schedule auction</button></form></section><section class="panel"><h2>Auction schedule</h2><div class="table-wrap"><table><thead><tr><th>Auction</th><th>Flower</th><th>Starts</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $a): ?><tr><td><?= e($a['title']) ?></td><td><?= e($a['flower_name']??'—') ?></td><td><?= e(date('d M Y H:i',strtotime($a['starts_at']))) ?></td><td><?= e($a['status']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4">No auctions scheduled.</td></tr><?php endif; ?></tbody></table></div></section></div><?php require __DIR__.'/_bottom.php'; ?>
